          yield {type: 'tool_use', toolCall: {id: 'c1', name: 't1', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use', usage: usage1};
          return;
        }
        yield {type: 'text', text: 'done'};
        yield {type: 'stop', stopReason: 'end_turn', usage: usage2};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(createSession('call tool'));

    expect(receivedUsage).toEqual({
      inputTokens: usage1.inputTokens + usage2.inputTokens,
      outputTokens: usage1.outputTokens + usage2.outputTokens,
